"use client";

function PatientNoteDialog({ onClose, onSaved }: { onClose: () => void; onSaved: () => void }) {
  const [patientId, setPatientId] = useState(patientDetailData[0].id);
  const [noteType, setNoteType] = useState("Progress note");
  const [priority, setPriority] = useState("Routine");
  const [note, setNote] = useState("");
  const [error, setError] = useState("");
  const patient = patientDetailData.find((item) => item.id === patientId) ?? patientDetailData[0];
  const saveNote = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (note.trim().length < 10) {
      setError("Write at least 10 characters so the clinical note is meaningful.");
      return;
    }
    onSaved();
  };
  return <div className="fixed inset-0 z-50 flex items-center justify-center overflow-y-auto bg-slate-950/40 p-4 backdrop-blur-sm" role="presentation" onMouseDown={(event) => event.target === event.currentTarget && onClose()}><div className="my-4 w-full max-w-2xl rounded-3xl border border-white/70 bg-white p-6 shadow-[0_28px_90px_rgba(15,23,42,0.24)] sm:p-8" role="dialog" aria-modal="true" aria-labelledby="patient-note-title"><div className="flex items-start justify-between gap-4 border-b border-slate-200 pb-5"><div><div className="text-[10px] font-semibold uppercase tracking-[0.18em] text-teal-700">Clinical documentation</div><h2 id="patient-note-title" className="mt-2 text-2xl font-semibold tracking-[-0.04em] text-slate-900">Add patient note</h2><p className="mt-1 text-sm text-slate-500">Create a time-stamped note for the selected patient record.</p></div><button type="button" onClick={onClose} className="rounded-xl border border-slate-200 p-2 text-slate-500 hover:bg-slate-50" aria-label="Close patient note dialog"><X size={18} /></button></div><form className="mt-6 space-y-5" onSubmit={saveNote} noValidate><div className="grid gap-4 sm:grid-cols-2"><label className="block text-[10px] font-semibold uppercase tracking-[0.14em] text-slate-500">Patient<select value={patientId} onChange={(event) => setPatientId(event.target.value)} className="mt-2 h-11 w-full rounded-xl border border-slate-200 bg-slate-50 px-3 text-sm font-normal normal-case tracking-normal text-slate-900 outline-none focus:border-teal-500 focus:ring-4 focus:ring-teal-500/10">{patientDetailData.map((item) => <option key={item.id} value={item.id}>{item.name} · {item.id}</option>)}</select></label><label className="block text-[10px] font-semibold uppercase tracking-[0.14em] text-slate-500">Note type<select value={noteType} onChange={(event) => setNoteType(event.target.value)} className="mt-2 h-11 w-full rounded-xl border border-slate-200 bg-slate-50 px-3 text-sm font-normal normal-case tracking-normal text-slate-900 outline-none focus:border-teal-500 focus:ring-4 focus:ring-teal-500/10"><option>Progress note</option><option>Consultation note</option><option>Discharge note</option><option>Care coordination</option><option>Handover note</option></select></label><label className="block text-[10px] font-semibold uppercase tracking-[0.14em] text-slate-500">Priority<select value={priority} onChange={(event) => setPriority(event.target.value)} className="mt-2 h-11 w-full rounded-xl border border-slate-200 bg-slate-50 px-3 text-sm font-normal normal-case tracking-normal text-slate-900 outline-none focus:border-teal-500 focus:ring-4 focus:ring-teal-500/10"><option>Routine</option><option>Important</option><option>Urgent</option></select></label><div className="rounded-xl border border-teal-100 bg-teal-50 px-3 py-2.5 text-xs text-teal-800"><div className="font-semibold">{patient.name}</div><div className="mt-1 text-teal-700/70">{patient.department} · {patient.doctor} · Current status: {patient.status}</div></div></div><label className="block text-[10px] font-semibold uppercase tracking-[0.14em] text-slate-500">Clinical note<textarea value={note} onChange={(event) => { setNote(event.target.value); setError(""); }} className={`mt-2 min-h-36 w-full resize-y rounded-xl border bg-slate-50 px-3 py-2 text-sm font-normal normal-case tracking-normal text-slate-900 outline-none placeholder:text-slate-400 focus:border-teal-500 focus:ring-4 focus:ring-teal-500/10 ${error ? "border-rose-300" : "border-slate-200"}`} placeholder={`Document ${noteType.toLowerCase()} details, findings, or care instructions...`} />{error && <span className="mt-1 block text-xs font-normal normal-case tracking-normal text-rose-600">{error}</span>}</label><div className="flex items-center justify-between gap-4 border-t border-slate-200 pt-5"><div className="text-xs text-slate-400">Author: Dr. Dev Nair · Today, 14 Sep 2026</div><div className="flex gap-3"><Button type="button" variant="secondary" onClick={onClose}>Cancel</Button><Button type="submit"><FileText size={15} /> Save note</Button></div></div></form></div></div>;
}

