function LabOrderDetails({ order, onClose, onUpdateStatus }: { order: { id: string; patient: string; patientId: string; age: number; test: string; section: string; doctor: string; department: string; priority: string; status: string; specimen: string; orderedAt: string; reason: string; instructions: string }; onClose: () => void; onUpdateStatus: (orderId: string) => void }) { const tone = order.status === "Completed" || order.status === "Verified" ? "green" as const : order.status === "Processing" ? "blue" as const : order.status === "Rejected" ? "rose" as const : "amber" as const; const actionLabel = order.status === "Rejected" ? "Request recollection" : order.status === "Pending" ? "Start processing" : order.status === "Processing" ? "Mark completed" : order.status === "Completed" ? "Verify result" : "Verified"; return <div className="fixed inset-0 z-50 bg-slate-950/35 backdrop-blur-sm" role="presentation" onMouseDown={(event) => event.target === event.currentTarget && onClose()}><aside className="ml-auto h-full w-full max-w-xl overflow-y-auto bg-white p-6 shadow-[-20px_0_70px_rgba(23,63,74,0.2)] sm:p-8" role="dialog" aria-modal="true" aria-labelledby="lab-order-details-title"><div className="flex items-start justify-between gap-4"><div><div className="text-[10px] font-semibold uppercase tracking-[0.18em] text-[#356a87]">Laboratory order</div><h2 id="lab-order-details-title" className="mt-2 text-2xl font-semibold tracking-[-0.04em] text-slate-900">{order.id}</h2><p className="mt-1 text-sm text-slate-500">{order.patient} · {order.patientId}</p></div><button type="button" onClick={onClose} className="rounded-xl border border-slate-200 p-2 text-slate-500 hover:bg-slate-50" aria-label="Close lab order details"><X size={18} /></button></div><div className="mt-6 rounded-3xl bg-gradient-to-br from-[#e6eff5] to-[#f5fafc] p-5"><div className="flex items-center justify-between gap-4"><div><div className="text-lg font-semibold text-slate-900">{order.test}</div><div className="mt-1 text-sm text-slate-600">{order.section} · {order.specimen}</div></div><Badge tone={tone}>{order.status}</Badge></div></div><div className="mt-6 grid gap-3 sm:grid-cols-2"><OrderDetail label="Patient" value={`${order.patient} · ${order.age} yrs`} /><OrderDetail label="Ordered by" value={order.doctor} /><OrderDetail label="Department" value={order.department} /><OrderDetail label="Priority" value={order.priority} /><OrderDetail label="Specimen" value={order.specimen} /><OrderDetail label="Ordered at" value={order.orderedAt} /></div><div className="mt-6 rounded-2xl border border-slate-200 bg-slate-50 p-4"><div className="text-[10px] font-bold uppercase tracking-[0.14em] text-slate-500">Clinical indication</div><p className="mt-2 text-sm leading-6 text-slate-700">{order.reason}</p></div><div className={`mt-4 rounded-2xl border p-4 ${order.status === "Rejected" ? "border-rose-200 bg-rose-50" : "border-cyan-100 bg-cyan-50/60"}`}><div className="text-[10px] font-bold uppercase tracking-[0.14em] text-slate-600">Collection / processing instructions</div><p className="mt-2 text-sm leading-6 text-slate-700">{order.instructions}</p></div><div className="mt-6 rounded-2xl border border-slate-200 p-4"><div className="text-[10px] font-bold uppercase tracking-[0.14em] text-slate-500">Order lifecycle</div><div className="mt-4 space-y-3"><Lifecycle label="Order created" time={order.orderedAt} active /><Lifecycle label="Specimen collected" time={order.status === "Pending" ? "Awaiting collection" : "10:28 AM"} active={order.status !== "Pending"} /><Lifecycle label="Processing" time={order.status === "Pending" ? "Queued" : order.status === "Processing" ? "In progress" : "Completed"} active={order.status !== "Pending"} /><Lifecycle label="Verification" time={order.status === "Verified" ? "Verified by lab manager" : "Awaiting review"} active={order.status === "Verified"} /></div></div><div className="mt-7 flex flex-col gap-3 border-t border-slate-200 pt-5 sm:flex-row"><Button variant="secondary" className="flex-1 justify-center" onClick={onClose}>Close</Button><Button className="flex-1 justify-center" disabled={order.status === "Verified"} onClick={() => onUpdateStatus(order.id)}><CheckCircle2 size={15} /> {actionLabel}</Button></div></aside></div>; }

function Lifecycle({ label, time, active }: { label: string; time: string; active: boolean }) { return <div className="flex items-center gap-3"><span className={`h-2.5 w-2.5 rounded-full ${active ? "bg-teal-500" : "bg-slate-200"}`} /><div className="flex flex-1 items-center justify-between gap-3"><span className={`text-sm ${active ? "font-semibold text-slate-800" : "text-slate-400"}`}>{label}</span><span className="text-xs text-slate-500">{time}</span></div></div>; }
function LabOrderDetail({ label, value }: { label: string; value: string }) { return <div><div className="text-[10px] font-semibold uppercase tracking-[0.12em] text-slate-400">{label}</div><div className="mt-1 font-semibold text-slate-800">{value}</div></div>; }
function OrderDetail({ label, value }: { label: string; value: string }) { return <LabOrderDetail label={label} value={value} />; }
