function LabResultRow({ result, statusTone, onOpen }: { result: LabResultWorklist; statusTone: (status: string) => "green" | "rose" | "amber"; onOpen: (result: LabResultWorklist) => void }) { return <div className="group flex w-full items-center gap-4 border-b border-slate-200/80 bg-[#f9fbfb]/80 px-5 py-4 transition last:border-b-0 hover:bg-white"><div className={`flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl ${result.flag.includes("Critical") ? "bg-rose-100 text-rose-700 ring-1 ring-rose-200" : "bg-[#eeecf8] text-[#6f6ba1] ring-1 ring-[#d8d4ed]"}`}><FlaskConical size={18} /></div><div className="w-44 shrink-0"><div className="font-semibold text-slate-900">{result.patient}</div><div className="mt-1 text-[11px] font-medium text-slate-400">{result.id} · {result.orderId} · {result.patientId}</div></div><div className="min-w-52 flex-1"><div className="truncate text-sm font-semibold text-slate-800">{result.test}</div><div className="mt-1 truncate text-xs font-medium text-slate-600">{result.result} · {result.section}</div></div><div className="w-36 shrink-0 text-sm text-slate-600">{result.reference}</div><div className="w-28 shrink-0"><Badge tone={result.flag.includes("Critical") ? "rose" : result.flag === "High" ? "amber" : "green"}>{result.flag}</Badge></div><div className="w-28 shrink-0"><Badge tone={statusTone(result.status)}>{result.status}</Badge></div><div className="w-36 shrink-0"><button type="button" onClick={() => onOpen(result)} className="inline-flex h-9 w-full items-center justify-center gap-1.5 rounded-xl bg-[#173f4a] px-2 text-[11px] font-semibold !text-white shadow-[0_6px_14px_rgba(23,63,74,0.16)] transition hover:bg-[#6f6ba1]"><Eye size={14} /> Open details</button></div></div>; }

function LabResultCard({ result, statusTone, onOpen }: { result: LabResultWorklist; statusTone: (status: string) => "green" | "rose" | "amber"; onOpen: (result: LabResultWorklist) => void }) { return <article className="bg-[#f9fbfb]/80 p-4"><div className="flex items-start justify-between gap-3"><div className="flex min-w-0 items-center gap-3"><div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl bg-[#eeecf8] text-[#6f6ba1]"><FlaskConical size={17} /></div><div className="min-w-0"><div className="truncate font-semibold text-slate-900">{result.patient}</div><div className="mt-1 text-xs text-slate-500">{result.id} · {result.patientId}</div></div></div><Badge tone={statusTone(result.status)}>{result.status}</Badge></div><div className="mt-4 grid grid-cols-2 gap-3 text-xs"><LabOrderDetail label="Test" value={result.test} /><LabOrderDetail label="Result" value={result.result} /><LabOrderDetail label="Reference" value={result.reference} /><LabOrderDetail label="Flag" value={result.flag} /><LabOrderDetail label="Section" value={result.section} /><LabOrderDetail label="Collected" value={result.collected} /></div><button type="button" onClick={() => onOpen(result)} className="mt-4 flex min-h-11 w-full items-center justify-center gap-2 rounded-xl bg-[#173f4a] px-3 py-2.5 text-xs font-semibold !text-white shadow-[0_8px_18px_rgba(23,63,74,0.14)] transition hover:bg-[#6f6ba1]"><Eye size={15} /> Open result details</button></article>; }

function LabResultDetails({ result, onClose, onUpdate }: { result: { id: string; orderId: string; patient: string; patientId: string; test: string; section: string; result: string; reference: string; flag: string; status: string; priority: string; collected: string; method: string; doctor: string; note: string }; onClose: () => void; onUpdate: (resultId: string, nextStatus: string) => void }) { const critical = result.flag.includes("Critical"); const nextStatus = result.status === "Pending review" ? "Verified" : result.status === "Verified" ? "Released" : result.status; const actionLabel = result.status === "Pending review" ? "Verify result" : result.status === "Verified" ? "Release report" : "Result released"; return <div className="fixed inset-0 z-50 bg-slate-950/35 backdrop-blur-sm" role="presentation" onMouseDown={(event) => event.target === event.currentTarget && onClose()}><aside className="ml-auto h-full w-full max-w-xl overflow-y-auto bg-white p-6 shadow-[-20px_0_70px_rgba(23,63,74,0.2)] sm:p-8" role="dialog" aria-modal="true" aria-labelledby="lab-result-details-title"><div className="flex items-start justify-between gap-4"><div><div className="text-[10px] font-semibold uppercase tracking-[0.18em] text-[#6f6ba1]">Laboratory result</div><h2 id="lab-result-details-title" className="mt-2 text-2xl font-semibold tracking-[-0.04em] text-slate-900">{result.id}</h2><p className="mt-1 text-sm text-slate-500">{result.patient} · {result.patientId} · {result.orderId}</p></div><button type="button" onClick={onClose} className="rounded-xl border border-slate-200 p-2 text-slate-500 hover:bg-slate-50" aria-label="Close result details"><X size={18} /></button></div><div className={`mt-6 rounded-3xl p-5 ${critical ? "bg-gradient-to-br from-rose-50 to-amber-50" : "bg-gradient-to-br from-[#eeecf8] to-[#f8f7fc]"}`}><div className="flex items-center justify-between gap-4"><div><div className="text-lg font-semibold text-slate-900">{result.test}</div><div className="mt-1 text-sm text-slate-600">{result.section} · {result.method}</div></div><Badge tone={critical ? "rose" : result.status === "Released" ? "green" : "amber"}>{result.status}</Badge></div><div className="mt-5 flex items-end justify-between gap-4"><div><div className="text-[10px] font-bold uppercase tracking-[0.14em] text-slate-500">Measured value</div><div className={`mt-1 text-3xl font-semibold tracking-[-0.05em] ${critical ? "text-rose-700" : "text-slate-900"}`}>{result.result}</div></div><div className="text-right"><div className="text-[10px] font-bold uppercase tracking-[0.14em] text-slate-500">Reference range</div><div className="mt-1 text-sm font-semibold text-slate-700">{result.reference}</div></div></div></div><div className="mt-6 grid gap-3 sm:grid-cols-2"><LabOrderDetail label="Patient" value={result.patient} /><LabOrderDetail label="Ordering clinician" value={result.doctor} /><LabOrderDetail label="Collected" value={result.collected} /><LabOrderDetail label="Section" value={result.section} /><LabOrderDetail label="Flag" value={result.flag} /><LabOrderDetail label="Priority" value={result.priority} /></div>{critical && <div className="mt-6 rounded-2xl border border-rose-200 bg-rose-50 p-4"><div className="flex items-center gap-2 text-[10px] font-bold uppercase tracking-[0.14em] text-rose-700"><AlertTriangle size={14} /> Critical value protocol</div><p className="mt-2 text-sm leading-6 text-rose-900">Notify {result.doctor}, document the communication time, and confirm read-back before releasing this result.</p><Button variant="secondary" className="mt-3 w-full justify-center">Record clinician notification</Button></div>}<div className="mt-6 rounded-2xl border border-slate-200 bg-slate-50 p-4"><div className="text-[10px] font-bold uppercase tracking-[0.14em] text-slate-500">Technologist / laboratory note</div><p className="mt-2 text-sm leading-6 text-slate-700">{result.note}</p></div><div className="mt-6 rounded-2xl border border-slate-200 p-4"><div className="text-[10px] font-bold uppercase tracking-[0.14em] text-slate-500">Result lifecycle</div><div className="mt-4 space-y-3"><Lifecycle label="Specimen received" time={result.collected} active /><Lifecycle label="Analysis completed" time="14 Sep 2026 · 10:36 AM" active /><Lifecycle label="Technologist review" time={result.status === "Pending review" ? "Awaiting review" : "Completed"} active={result.status !== "Pending review"} /><Lifecycle label="Report released" time={result.status === "Released" ? "Released to clinician" : "Awaiting sign-off"} active={result.status === "Released"} /></div></div><div className="mt-7 flex flex-col gap-3 border-t border-slate-200 pt-5 sm:flex-row"><Button variant="secondary" className="flex-1 justify-center" onClick={onClose}>Close</Button><Button className="flex-1 justify-center" disabled={result.status === "Released"} onClick={() => onUpdate(result.id, nextStatus)}><CheckCircle2 size={15} /> {actionLabel}</Button></div></aside></div>; }
type LabReport = { id: string; name: string; category: string; period: string; owner: string; status: string; updated: string; summary: string; metrics: Array<{ label: string; value: string; note: string }>; highlights: string[] };

export function LabReportsPage() {
  const reports: LabReport[] = [
    { id: "LAB-RPT-401", name: "Daily laboratory operations", category: "Operations", period: "14 Sep 2026", owner: "Priya Menon", status: "Ready", updated: "Today, 11:42 AM", summary: "Accession volume, section workload, turnaround performance, rejected specimens, and critical-value communication for the current laboratory shift.", metrics: [{ label: "Accessions", value: "57", note: "Today" }, { label: "Within SLA", value: "92%", note: "Target ≥ 90%" }, { label: "Critical values", value: "02", note: "Open follow-up" }], highlights: ["Hematology processed 38 tests with 6 awaiting verification.", "Two critical values require documented clinician read-back.", "Four investigations exceeded the target turnaround time."] },
    { id: "LAB-RPT-402", name: "Turnaround time and SLA", category: "Quality", period: "September 2026", owner: "Quality team", status: "Published", updated: "Today, 09:18 AM", summary: "Turnaround performance by section, priority, and test category with overdue investigation analysis.", metrics: [{ label: "Average TAT", value: "42 min", note: "Target 60 min" }, { label: "Within SLA", value: "92%", note: "↑ 4.8%" }, { label: "Overdue", value: "04", note: "Needs review" }], highlights: ["Emergency and critical samples remain within priority SLA.", "Microbiology cultures are the largest source of extended TAT.", "Analyzer utilization remained below the 80% escalation threshold."] },
    { id: "LAB-RPT-403", name: "Section utilization report", category: "Utilization", period: "August 2026", owner: "Operations team", status: "Published", updated: "13 Sep 2026", summary: "Test volumes, analyzer utilization, staffing load, and capacity pressure across laboratory sections.", metrics: [{ label: "Total tests", value: "1,284", note: "Monthly volume" }, { label: "Analyzer load", value: "74%", note: "Core instruments" }, { label: "Peak section", value: "Hematology", note: "38% of volume" }], highlights: ["Hematology remains the highest-volume section.", "Biochemistry capacity is stable for the next planning cycle.", "No analyzer downtime exceeded the reporting threshold."] },
    { id: "LAB-RPT-404", name: "Critical values and communication", category: "Safety", period: "Q3 2026", owner: "Clinical governance", status: "Needs sign-off", updated: "12 Sep 2026", summary: "Critical result events, clinician notifications, read-back compliance, and unresolved communication exceptions.", metrics: [{ label: "Critical events", value: "38", note: "Quarter to date" }, { label: "Read-back", value: "97%", note: "Compliance" }, { label: "Open exceptions", value: "02", note: "Needs escalation" }], highlights: ["Two critical result communications remain open for manager review.", "Read-back compliance is above the 95% safety target.", "Emergency department has the highest critical-result volume."] },
  ];
  const [search, setSearch] = useState("");
  const [filter, setFilter] = useState("All");
  const [selectedReport, setSelectedReport] = useState<LabReport | null>(null);
  const [reportsState, setReportsState] = useState(reports);
  const [message, setMessage] = useState("");
  const visible = reportsState.filter((report) => `${report.id} ${report.name} ${report.category} ${report.period} ${report.owner} ${report.status}`.toLowerCase().includes(search.toLowerCase()) && (filter === "All" || report.category === filter || report.status === filter));
  const publishReport = (reportId: string) => { setReportsState((current) => current.map((report) => report.id === reportId ? { ...report, status: "Published", updated: "Just now" } : report)); setSelectedReport((current) => current ? { ...current, status: "Published", updated: "Just now" } : current); setMessage(`${reportId} published successfully.`); };

  return <HmsShell role="LAB_MANAGER" title="Lab reports" description="Turn laboratory activity into trusted operational, quality, utilization, and safety decisions." breadcrumbs={["Laboratory", "Reports"]} actions={<><Button variant="secondary"><Download size={15} /> Export library</Button><Button><FileBarChart2 size={15} /> Generate report</Button></>}>
    <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4"><StatCard label="Reports this month" value="18" note="4 published this week" icon={FileBarChart2} tone="blue" /><StatCard label="Operational score" value="94%" note="↑ 3.2% this period" icon={Activity} tone="green" /><StatCard label="Quality compliance" value="97%" note="Read-back and TAT" icon={CheckCircle2} tone="amber" /><StatCard label="Needs sign-off" value="02" note="Manager review required" icon={AlertTriangle} tone="rose" /></div>
    <section className="mt-6"><div className="mb-6 flex items-end justify-between gap-4 border-l-4 border-[#7c83b5] bg-[#173f4a] px-6 py-5 shadow-[0_16px_35px_rgba(23,63,74,0.16)]"><div><div className="text-[10px] font-bold uppercase tracking-[0.2em] text-[#d3d5f0]">Laboratory intelligence</div><h3 className="mt-2 text-2xl font-semibold tracking-[-0.04em] text-white">Reports library</h3><p className="mt-1 text-sm text-white/60">Review the signals that keep diagnostic quality, safety, and capacity under control.</p></div><div className="hidden text-right sm:block"><div className="text-3xl font-semibold tracking-[-0.05em] text-white">{visible.length}</div><div className="text-[10px] font-semibold uppercase tracking-[0.14em] text-[#d3d5f0]/70">Visible reports</div></div></div>
      <div className="mb-3 flex flex-col gap-3 rounded-2xl border border-slate-200/80 bg-white/80 p-3 shadow-sm"><div className="flex min-w-0 items-center gap-2 rounded-xl border border-slate-200 bg-slate-50 px-3 py-2.5"><Search size={15} className="shrink-0 text-slate-400" /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search report, category, period, or owner" className="min-w-0 w-full bg-transparent text-xs outline-none placeholder:text-slate-400" /></div><div className="flex gap-1 overflow-x-auto">{["All", "Operations", "Quality", "Utilization", "Safety", "Published", "Needs sign-off"].map((item) => <button key={item} type="button" onClick={() => setFilter(item)} className={`shrink-0 rounded-lg px-3 py-2 text-xs font-semibold transition ${filter === item ? "bg-[#173f4a] text-white" : "text-slate-500 hover:bg-[#eeecf8] hover:text-[#6f6ba1]"}`}>{item}</button>)}</div></div>
      <div className="overflow-hidden rounded-2xl border border-slate-200/80 bg-[#eef3f4] shadow-[0_12px_30px_rgba(23,63,74,0.06)]"><div className="hidden overflow-x-auto lg:block"><div className="min-w-[1200px]"><div className="flex items-center gap-4 border-b border-slate-200 bg-slate-100/80 px-5 py-3 text-[10px] font-semibold uppercase tracking-[0.14em] text-slate-400"><span className="w-12 shrink-0" /><span className="w-64 shrink-0">Report</span><span className="w-28 shrink-0">Category</span><span className="w-32 shrink-0">Period</span><span className="min-w-40 flex-1">Owner</span><span className="w-28 shrink-0">Status</span><span className="w-32 shrink-0">Updated</span><span className="w-36 shrink-0 text-center">Action</span></div>{visible.map((report) => <LabReportRow key={report.id} report={report} onOpen={setSelectedReport} />)}</div></div><div className="divide-y divide-slate-200 lg:hidden">{visible.map((report) => <LabReportCard key={report.id} report={report} onOpen={setSelectedReport} />)}</div>{visible.length === 0 && <div className="p-10 text-center text-sm text-slate-500">No reports match your search or filter.</div>}</div>
    </section>
    {selectedReport && <LabReportDetails report={selectedReport} onClose={() => setSelectedReport(null)} onPublish={publishReport} />}{message && <div className="fixed bottom-5 right-5 z-40 flex items-center gap-2 rounded-2xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm font-medium text-emerald-800 shadow-lg"><CheckCircle2 size={17} /> {message}</div>}
  </HmsShell>;
}

function LabReportRow({ report, onOpen }: { report: LabReport; onOpen: (report: LabReport) => void }) { return <div className="group flex min-w-0 items-center gap-4 border-b border-slate-200/80 bg-[#f9fbfb]/80 px-5 py-4 transition last:border-b-0 hover:bg-white"><div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl bg-[#eeecf8] text-[#6f6ba1] ring-1 ring-[#d8d4ed]"><FileBarChart2 size={18} /></div><div className="w-64 shrink-0"><div className="font-semibold text-slate-900">{report.name}</div><div className="mt-1 text-[11px] font-medium text-slate-400">{report.id}</div></div><div className="w-28 shrink-0"><Badge tone={report.category === "Safety" ? "rose" : report.category === "Quality" ? "blue" : report.category === "Operations" ? "green" : "amber"}>{report.category}</Badge></div><div className="w-32 shrink-0 text-sm font-medium text-slate-700">{report.period}</div><div className="min-w-40 flex-1 text-sm text-slate-600">{report.owner}</div><div className="w-28 shrink-0"><Badge tone={report.status === "Published" || report.status === "Ready" ? "green" : "amber"}>{report.status}</Badge></div><div className="w-32 shrink-0 text-xs text-slate-500">{report.updated}</div><div className="w-36 shrink-0"><button type="button" onClick={() => onOpen(report)} className="inline-flex h-9 w-full items-center justify-center gap-1.5 whitespace-nowrap rounded-xl bg-[#173f4a] px-2 text-[11px] font-semibold !text-white shadow-[0_6px_14px_rgba(23,63,74,0.16)] transition hover:bg-[#6f6ba1]"><Eye size={14} /> Open details</button></div></div>; }

function LabReportCard({ report, onOpen }: { report: LabReport; onOpen: (report: LabReport) => void }) { return <article className="box-border flex w-full max-w-full min-w-0 flex-col overflow-hidden bg-[#f9fbfb]/80 p-4"><div className="flex min-w-0 items-start justify-between gap-3"><div className="flex min-w-0 items-center gap-3"><div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl bg-[#eeecf8] text-[#6f6ba1]"><FileBarChart2 size={17} /></div><div className="min-w-0"><div className="truncate font-semibold text-slate-900">{report.name}</div><div className="mt-1 text-xs text-slate-500">{report.id} · {report.period}</div></div></div><Badge tone={report.status === "Published" || report.status === "Ready" ? "green" : "amber"}>{report.status}</Badge></div><div className="mt-4 grid min-w-0 grid-cols-2 gap-3 text-xs"><LabOrderDetail label="Category" value={report.category} /><LabOrderDetail label="Owner" value={report.owner} /><LabOrderDetail label="Updated" value={report.updated} /><LabOrderDetail label="Coverage" value={report.summary.slice(0, 42) + "..."} /></div><button type="button" onClick={() => onOpen(report)} className="box-border mt-4 flex min-h-11 w-full max-w-full min-w-0 items-center justify-center gap-2 overflow-hidden rounded-xl bg-[#173f4a] px-3 py-2.5 text-xs font-semibold !text-white shadow-[0_8px_18px_rgba(23,63,74,0.14)] transition hover:bg-[#6f6ba1]"><Eye size={15} /> <span className="truncate">Open result details</span></button></article>; }

function LabReportDetails({ report, onClose, onPublish }: { report: LabReport; onClose: () => void; onPublish: (reportId: string) => void }) { const canPublish = report.status === "Ready" || report.status === "Needs sign-off"; return <div className="fixed inset-0 z-50 bg-slate-950/35 backdrop-blur-sm" role="presentation" onMouseDown={(event) => event.target === event.currentTarget && onClose()}><aside className="ml-auto h-full w-full max-w-2xl overflow-y-auto bg-white p-6 shadow-[-20px_0_70px_rgba(23,63,74,0.2)] sm:p-8" role="dialog" aria-modal="true" aria-labelledby="lab-report-details-title"><div className="flex items-start justify-between gap-4"><div><div className="text-[10px] font-semibold uppercase tracking-[0.18em] text-[#6f6ba1]">Laboratory report</div><h2 id="lab-report-details-title" className="mt-2 text-2xl font-semibold tracking-[-0.04em] text-slate-900">{report.name}</h2><p className="mt-1 text-sm text-slate-500">{report.id} · {report.period}</p></div><button type="button" onClick={onClose} className="rounded-xl border border-slate-200 p-2 text-slate-500 hover:bg-slate-50" aria-label="Close report details"><X size={18} /></button></div><div className="mt-6 rounded-3xl bg-gradient-to-br from-[#eeecf8] to-[#f8f7fc] p-5"><div className="flex items-center justify-between gap-4"><div><div className="text-lg font-semibold text-slate-900">{report.category} report</div><div className="mt-1 text-sm text-slate-600">Owned by {report.owner}</div></div><Badge tone={report.status === "Published" ? "green" : "amber"}>{report.status}</Badge></div></div><div className="mt-6 grid gap-3 sm:grid-cols-3">{report.metrics.map((metric) => <div key={metric.label} className="rounded-2xl border border-slate-200 bg-white p-3"><div className="text-[10px] font-semibold uppercase tracking-[0.12em] text-slate-400">{metric.label}</div><div className="mt-2 text-xl font-semibold tracking-[-0.04em] text-[#6f6ba1]">{metric.value}</div><div className="mt-1 text-[11px] text-slate-500">{metric.note}</div></div>)}</div><div className="mt-6 rounded-2xl border border-slate-200 bg-slate-50 p-4"><div className="text-[10px] font-bold uppercase tracking-[0.14em] text-slate-500">Report coverage</div><p className="mt-2 text-sm leading-6 text-slate-700">{report.summary}</p></div><div className="mt-6 rounded-2xl border border-slate-200 p-4"><div className="text-[10px] font-bold uppercase tracking-[0.14em] text-slate-500">Key findings</div><div className="mt-3 space-y-3">{report.highlights.map((highlight) => <div key={highlight} className="flex items-start gap-2 text-sm leading-6 text-slate-700"><CheckCircle2 size={16} className="mt-1 shrink-0 text-teal-600" />{highlight}</div>)}</div></div><div className="mt-6 rounded-2xl border border-slate-200 p-4"><div className="flex items-center justify-between gap-3"><div><div className="text-sm font-semibold text-slate-800">Report sign-off</div><div className="mt-1 text-xs text-slate-500">Last updated {report.updated}</div></div><Badge tone={report.status === "Published" ? "green" : "amber"}>{report.status === "Published" ? "Released" : "Pending review"}</Badge></div></div><div className="mt-7 flex flex-col gap-3 border-t border-slate-200 pt-5 sm:flex-row"><Button variant="secondary" className="flex-1 justify-center"><Download size={15} /> Export report</Button><Button className="flex-1 justify-center" disabled={!canPublish} onClick={() => onPublish(report.id)}><CheckCircle2 size={15} /> {canPublish ? "Sign off and publish" : "Report published"}</Button></div></aside></div>; }

export function PharmacyDashboardPage() { return <HmsShell role="PHARMACIST" title="Medication center" description="Monitor prescriptions, stock, and dispensing workflow." breadcrumbs={["Pharmacy", "Dashboard"]} actions={<Button>Dispense</Button>}><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4"><StatCard label="Pending prescriptions" value="18" note="5 due within 30 mins" icon={ClipboardList} tone="blue" /><StatCard label="Low stock" value="07" note="Action required" icon={Pill} tone="amber" /><StatCard label="Dispensed" value="142" note="Today" icon={CheckCircle2} tone="green" /><StatCard label="Expiring" value="05" note="This week" icon={AlertTriangle} tone="rose" /></div></HmsShell>; }
export function PharmacyPrescriptionsPage() { return <HmsShell role="PHARMACIST" title="Prescriptions" description="Verify and dispense medication requests." breadcrumbs={["Pharmacy", "Prescriptions"]}><SectionCard title="Prescription queue" subtitle="Pending"><DataTable headers={['Patient','Doctor','Medicines','Status']} rows={[['Meera Iyer','Dr. Dev Nair','Paracetamol','Ready'],['Arjun Nair','Dr. Asha Sharma','Aspirin','Pending verification']]} /></SectionCard></HmsShell>; }
export function PharmacyInventoryPage() { return <HmsShell role="PHARMACIST" title="Inventory" description="Track stock positions, low inventory, and expiries." breadcrumbs={["Pharmacy", "Inventory"]}><SectionCard title="Medicine inventory" subtitle="Medications"><DataTable headers={['Medicine','Batch','Stock','Expiry']} rows={[['Paracetamol','P-1001','320 packs','2027-02'],['Amoxicillin','A-4002','18 packs','2026-11']]} /></SectionCard></HmsShell>; }
export function PharmacyReportsPage() { return <HmsShell role="PHARMACIST" title="Reports" description="Stock and dispensing performance analytics." breadcrumbs={["Pharmacy", "Reports"]}><SectionCard title="Monthly summary" subtitle="Current period"><DataTable headers={['Metric','Value']} rows={[['Prescriptions dispensed','1,284'],['Low stock items','07'],['Inventory value','₹4.8L']]} /></SectionCard></HmsShell>; }

export function AccountsDashboardPage() { return <HmsShell role="ACCOUNTANT" title="Finance dashboard" description="Revenue, invoices, and payment performance at a glance." breadcrumbs={["Accounts", "Dashboard"]} actions={<Button>New invoice</Button>}><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4"><StatCard label="Revenue" value="₹28.4L" note="This month" icon={WalletCards} tone="green" /><StatCard label="Invoices" value="482" note="92 paid" icon={ReceiptText} tone="blue" /><StatCard label="Outstanding" value="₹4.2L" note="14 invoices open" icon={CreditCard} tone="amber" /><StatCard label="Expenses" value="₹9.1L" note="Operational" icon={FileBarChart2} tone="rose" /></div></HmsShell>; }
export function AccountsInvoicesPage() { return <HmsShell role="ACCOUNTANT" title="Invoices" description="Review billing entries and invoice details." breadcrumbs={["Accounts", "Invoices"]}><SectionCard title="Invoice register" subtitle="Current cycle"><DataTable headers={['Invoice','Patient','Amount','Status']} rows={[['INV-2098','Fatima Khan','₹4,240','Pending'],['INV-2099','Arjun Nair','₹18,700','Partial']]} /></SectionCard></HmsShell>; }
export function AccountsPaymentsPage() { return <HmsShell role="ACCOUNTANT" title="Payments" description="Track cash, digital, and insurance settlements." breadcrumbs={["Accounts", "Payments"]}><SectionCard title="Payment ledger" subtitle="Transactions"><DataTable headers={['Receipt','Patient','Method','Amount','Status']} rows={[['RCPT-901','Fatima Khan','UPI','₹4,240','Received'],['RCPT-902','Meera Iyer','Card','₹2,400','Received']]} /></SectionCard></HmsShell>; }
export function AccountsReportsPage() { return <HmsShell role="ACCOUNTANT" title="Reports" description="Revenue, trends, and payment clearing analyses." breadcrumbs={["Accounts", "Reports"]}><SectionCard title="Finance summary" subtitle="This quarter"><DataTable headers={['Metric','Value']} rows={[['Revenue','₹84.2L'],['Expenses','₹26.5L'],['Outstanding','₹4.2L']]} /></SectionCard></HmsShell>; }

export function StaffDashboardPage() {
  return (
    <HmsShell role="STAFF" title="Team workspace" description="Access assigned tasks, notifications, and shared operational updates." breadcrumbs={["Staff", "Dashboard"]}>
      <div className="grid gap-4 md:grid-cols-3">
        <StatCard label="Tasks" value="12" note="3 due today" icon={ClipboardList} tone="blue" />
        <StatCard label="Messages" value="04" note="2 unread" icon={Bell} tone="amber" />
        <StatCard label="Alerts" value="02" note="Needs review" icon={AlertTriangle} tone="rose" />
      </div>
      <div className="mt-6 grid gap-4 md:grid-cols-2 xl:grid-cols-3">
        {staffList.map((member) => (
          <PremiumStaffCard key={member.id} member={member} />
        ))}
      </div>
    </HmsShell>
  );
}
export function StaffNotificationsPage() { return <HmsShell role="STAFF" title="Notifications" description="Review important updates and operational announcements." breadcrumbs={["Staff", "Notifications"]}><SectionCard title="Inbox" subtitle="Unread items"><DataTable headers={['Title','Category','Time','Status']} rows={notifications.map((n) => [n.title, n.category, n.time, n.unread ? 'Unread' : 'Read'])} /></SectionCard></HmsShell>; }
